use std::collections::HashMap;impl Solution{pub fn can_win(s:String)->bool{fn f(s:String,m:&mut HashMap<String,bool>)->bool{if let Some(&v)=m.get(&s){return v}let mut b=s.as_bytes().to_vec();for i in 0..b.len().saturating_sub(1){if b[i]==b'+'&&b[i+1]==b'+'{b[i]=b'-';b[i+1]=b'-';let x=String::from_utf8(b.clone()).unwrap();if !f(x,m){m.insert(s.clone(),true);return true}b[i]=b'+';b[i+1]=b'+';}}m.insert(s,false);false}f(s,&mut HashMap::new())}}
